* {
  margin: 0;
  padding: 0;
  box-sizing: border-box;
}

html {
  scroll-behavior: smooth;
}

body {
  font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', 'Roboto', 'Oxygen',
    'Ubuntu', 'Cantarell', 'Fira Sans', 'Droid Sans', 'Helvetica Neue', sans-serif;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  background: linear-gradient(135deg, #1a1a2e 0%, #16213e 100%);
  color: #e0e0e0;
  line-height: 1.6;
  min-height: 100vh;
}

/* Skip link for keyboard navigation */
.skip-link {
  position: absolute;
  top: -40px;
  left: 0;
  background: #0f3460;
  color: #fff;
  padding: 8px 12px;
  text-decoration: none;
  border-radius: 0 0 4px 0;
  z-index: 100;
}

.skip-link:focus {
  top: 0;
}

/* Main layout */
main {
  padding: 40px 20px;
  max-width: 600px;
  margin: 0 auto;
}

.page-header {
  margin-bottom: 40px;
  text-align: center;
}

h1 {
  font-size: 2rem;
  font-weight: 700;
  color: #ffffff;
  margin-bottom: 12px;
  letter-spacing: -0.5px;
}

/* Form container */
.form-container {
  background: rgba(15, 52, 96, 0.5);
  border: 1px solid rgba(224, 224, 224, 0.1);
  border-radius: 12px;
  padding: 32px;
  backdrop-filter: blur(10px);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.3);
}

/* Form field wrapper */
.form-field {
  margin-bottom: 32px;
}

.form-field:last-child {
  margin-bottom: 0;
}

/* Fieldset and legend */
fieldset {
  border: none;
  padding: 0;
  margin: 0;
}

legend {
  font-size: 1.1rem;
  font-weight: 600;
  color: #ffffff;
  margin-bottom: 20px;
  padding: 0;
  width: 100%;
}

legend span {
  color: #ff6b6b;
  margin-left: 4px;
}

/* Radio group container */
.radio-group {
  display: flex;
  flex-direction: column;
  gap: 16px;
}

/* Individual radio option */
.radio-option {
  display: flex;
  align-items: center;
  padding: 14px 16px;
  background: rgba(255, 255, 255, 0.05);
  border: 2px solid transparent;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.2s ease;
}

.radio-option:hover {
  background: rgba(255, 255, 255, 0.08);
  border-color: rgba(224, 224, 224, 0.2);
}

/* Radio input styling */
input[type="radio"] {
  appearance: none;
  -webkit-appearance: none;
  -moz-appearance: none;
  width: 20px;
  height: 20px;
  border: 2px solid #666;
  border-radius: 50%;
  background: transparent;
  cursor: pointer;
  margin-right: 12px;
  flex-shrink: 0;
  transition: all 0.2s ease;
  position: relative;
}

input[type="radio"]:hover {
  border-color: #888;
  box-shadow: 0 0 8px rgba(136, 136, 136, 0.3);
}

input[type="radio"]:focus {
  outline: 2px solid #0f9fff;
  outline-offset: 2px;
  border-color: #0f9fff;
}

input[type="radio"]:checked {
  background: linear-gradient(135deg, #0f9fff 0%, #0a73d9 100%);
  border-color: #0f9fff;
  box-shadow: 0 0 12px rgba(15, 159, 255, 0.4);
}

input[type="radio"]:checked::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  width: 8px;
  height: 8px;
  background: white;
  border-radius: 50%;
  transform: translate(-50%, -50%);
}

input[type="radio"]:disabled {
  background: #333;
  border-color: #555;
  cursor: not-allowed;
  opacity: 0.6;
}

/* Radio label */
.radio-option label {
  cursor: pointer;
  font-size: 1rem;
  font-weight: 500;
  color: #e0e0e0;
  margin: 0;
  transition: color 0.2s ease;
  flex: 1;
}

.radio-option:hover label {
  color: #ffffff;
}

input[type="radio"]:checked ~ label {
  color: #ffffff;
  font-weight: 600;
}

input[type="radio"]:disabled ~ label {
  color: #888;
  cursor: not-allowed;
}

/* Submit button */
.submit-button {
  width: 100%;
  padding: 14px 24px;
  font-size: 1rem;
  font-weight: 600;
  color: white;
  background: linear-gradient(135deg, #0f9fff 0%, #0a73d9 100%);
  border: none;
  border-radius: 8px;
  cursor: pointer;
  transition: all 0.3s ease;
  box-shadow: 0 4px 16px rgba(15, 159, 255, 0.3);
  margin-top: 8px;
}

.submit-button:hover {
  background: linear-gradient(135deg, #1ba3ff 0%, #1581e8 100%);
  box-shadow: 0 6px 20px rgba(15, 159, 255, 0.4);
  transform: translateY(-2px);
}

.submit-button:focus {
  outline: 2px solid #ffffff;
  outline-offset: 2px;
}

.submit-button:active {
  transform: translateY(0);
}

.submit-button:disabled {
  background: linear-gradient(135deg, #444 0%, #333 100%);
  cursor: not-allowed;
  box-shadow: none;
  opacity: 0.6;
}

/* Status message */
.status-message {
  margin-top: 24px;
  padding: 14px 16px;
  border-radius: 8px;
  font-size: 0.95rem;
  min-height: 0;
  opacity: 0;
  transition: opacity 0.3s ease;
}

.status-message.show {
  opacity: 1;
}

.status-message.success {
  background: rgba(76, 175, 80, 0.2);
  border: 1px solid rgba(76, 175, 80, 0.4);
  color: #4caf50;
}

.status-message.error {
  background: rgba(244, 67, 54, 0.2);
  border: 1px solid rgba(244, 67, 54, 0.4);
  color: #f44336;
}

/* Responsive design */
@media (max-width: 600px) {
  main {
    padding: 24px 16px;
  }

  .form-container {
    padding: 24px;
  }

  h1 {
    font-size: 1.5rem;
  }

  legend {
    font-size: 1rem;
  }

  .radio-option {
    padding: 12px 14px;
  }

  input[type="radio"] {
    width: 18px;
    height: 18px;
  }
}

/* Forced colors mode support (high contrast) */
@media (prefers-contrast: more) {
  .form-container {
    border: 2px solid currentColor;
  }

  input[type="radio"] {
    border-width: 3px;
  }

  .submit-button {
    border: 2px solid currentColor;
  }
}

/* Reduced motion support */
@media (prefers-reduced-motion: reduce) {
  * {
    animation: none !important;
    transition: none !important;
  }
}
