      id: v.id,
      impact: v.impact,
      description: v.description,
      targets: v.nodes.map(n => n.target)
    })),
    bp: bp.map(v => ({
      id: v.id,
      description: v.description,
      targets: v.nodes.map(n => n.target)
    }))
  }, null, 2));

  if (wcag.length > 0) {
    console.error(`\n❌ Found ${wcag.length} WCAG violation(s)`);
    process.exit(1);
  } else if (bp.length > 0) {
    console.error(`\n⚠️  Found ${bp.length} best-practice warning(s)`);
  } else {
    console.error("\n✅ All accessibility checks passed!");
  }
}

testAccessibility();
